rows.raw:
CALL {
  MATCH (p:Person)-[:REVIEWED]->(m:Movie {rating: {rating}})
  WITH m.summary AS summary
  UNWIND split(summary, ' ') AS word
  RETURN count(word) AS word_count
}
WITH avg(word_count) AS average_words
RETURN average_words;

